<?php $pageTitle=page_title('Farmer dashboard'); $page='farmer-dashboard'; ?>
<div class="dashboard-head reveal"><div><span class="eyebrow">Farm overview</span><h1>Welcome to your farm stand.</h1><p>Keep stock accurate, answer pre-orders quickly, and prepare a smooth pickup.</p></div><a class="btn" href="<?= e(url('farmer-product-form')) ?>"><?= icon('plus') ?> Add product</a></div>
<div class="stat-grid"><article class="card stat-card"><span class="stat-label"><?= icon('orders') ?> Total orders</span><strong class="stat-value"><?= (int)$stats['orders'] ?></strong><span class="stat-note">All recorded pre-orders</span></article><article class="card stat-card"><span class="stat-label"><?= icon('bell') ?> Needs response</span><strong class="stat-value"><?= (int)$stats['pending'] ?></strong><span class="stat-note">Waiting for acceptance</span></article><article class="card stat-card"><span class="stat-label"><?= icon('package') ?> Active products</span><strong class="stat-value"><?= (int)$stats['products'] ?></strong><span class="stat-note">Visible weekly listings</span></article><article class="card stat-card"><span class="stat-label"><?= icon('chart') ?> Booked value</span><strong class="stat-value" style="font-size:1.6rem"><?= money($stats['booked']/100) ?></strong><span class="stat-note">Accepted, ready, completed</span></article></div>
<div class="content-card card mt-3"><div class="content-head"><div><h2>Pre-order queue</h2><p>Prioritize new orders, accepted baskets, and ready pickups.</p></div><a class="btn btn-light btn-sm" href="<?= e(url('farmer-orders')) ?>">All orders</a></div><?php if($recentOrders): ?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Pickup</th><th>Value</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($recentOrders as $order): ?><tr><td><strong><?= e($order['order_number']) ?></strong><br><small class="text-muted"><?= format_date($order['created_at'],'M j · g:i A') ?></small></td><td><?= e($order['customer_name']) ?></td><td><?= format_date($order['pickup_date'] ?? $order['created_at'],'M j, Y') ?><br><small class="text-muted"><?= e($order['market_name']) ?></small></td><td><strong><?= money($order['subtotal_cents']/100) ?></strong></td><td><?= status_pill($order['status']) ?></td><td><a class="btn btn-light btn-sm" href="<?= e(url('farmer-order',['id'=>$order['id']])) ?>">Open</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><span class="empty-state-icon">📦</span><h3>No pre-orders yet</h3><p>Customer orders will appear here after you publish active stock.</p></div><?php endif; ?></div>
<div class="detail-grid mt-3"><div class="content-card card"><div class="content-head"><div><h2>Low-stock watch</h2><p>Listings with five or fewer units.</p></div><a class="btn btn-light btn-sm" href="<?= e(url('farmer-products')) ?>">Manage stock</a></div><?php if($lowStockProducts): ?><div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th></th></tr></thead><tbody><?php foreach($lowStockProducts as $product): ?><tr><td><div class="table-product"><span class="table-thumb">🥬</span><strong><?= e($product['name']) ?></strong></div></td><td><?= money($product['price']) ?></td><td><?= status_pill((int)$product['stock_quantity']===0?'sold_out':'active') ?> <strong><?= (int)$product['stock_quantity'] ?></strong></td><td><a class="btn btn-light btn-sm" href="<?= e(url('farmer-product-form',['id'=>$product['id']])) ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><span class="empty-state-icon">✅</span><h3>Stock levels look healthy</h3><p>No active listing is critically low right now.</p></div><?php endif; ?></div>
<div class="content-card card"><div class="content-head"><div><h2>Recent activity</h2><p>Order and review notifications.</p></div></div><?php if($recentNotifications): ?><div class="timeline"><?php foreach($recentNotifications as $note): ?><div class="timeline-item"><strong><?= e($note['title']) ?></strong><span><?= e($note['message']) ?> · <?= e(time_ago($note['created_at'])) ?></span></div><?php endforeach; ?></div><?php else: ?><p class="text-muted">No recent activity.</p><?php endif; ?></div></div>
<div class="content-card card mt-3"><div class="content-head"><div><h2>Latest customer reviews</h2><p>Reply publicly from the review card.</p></div></div><?php if($recentReviews): ?><div class="review-grid"><?php foreach($recentReviews as $review): ?><article class="card review-card"><div class="review-head"><span class="user-avatar"><?= e(initials($review['customer_name'])) ?></span><div><strong><?= e($review['customer_name']) ?></strong><time><?= e($review['product_name']) ?></time></div><span style="margin-left:auto"><?= star_display((float)$review['rating'],false) ?></span></div><p><?= e($review['comment']) ?></p><?php if($review['response']): ?><div class="review-reply"><?= e($review['response']) ?></div><?php else: ?><form class="mt-2" method="post" action="<?= e(url('farmer-review-reply')) ?>"><?= csrf_field() ?><input type="hidden" name="review_id" value="<?= (int)$review['id'] ?>"><label class="sr-only" for="reply_<?= (int)$review['id'] ?>">Reply to review</label><textarea id="reply_<?= (int)$review['id'] ?>" name="response" maxlength="1000" placeholder="Write a public reply…" required style="min-height:85px"></textarea><button class="btn btn-light btn-sm mt-2" type="submit">Reply</button></form><?php endif; ?></article><?php endforeach; ?></div><?php else: ?><p class="text-muted">No published reviews yet.</p><?php endif; ?></div>
